def prime_fib(n: int):
    def is_prime(num: int) -> bool:
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    def fib_gen():
        a, b = 0, 1
        while True:
            yield a
            a, b = b, a + b

